  `leftarmcolor` int(11) NOT NULL,
  `rightarmcolor` int(11) NOT NULL,
  `leftlegcolor` int(11) NOT NULL,
  `rightlegcolor` int(11) NOT NULL,
  `bc` tinyint(1) NOT NULL,
  `hat` int(11) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

